"procedure": [],
"numbers_conditions": [
{"text": "Высота гряд: 10–20 м.", "claims": ["c2"]},
{"text": "Длина гряд: несколько километров.", "claims": ["c2"]},
{"text": "Ширина гряд: несколько сотен метров.", "claims": ["c2"]},
{"text": "Место: нижние спрямлённые участки проток, их осевые части.", "claims": ["c1"]},
{"text": "Условие: такие гряды характерны не для всех дельт, а для некоторых.", "claims": ["c2"]}
],
